"""The runtime library for Python code generated by tsurara (design.md 18.9).

Two layers: the types layer (``TypeDefs``, ``File``, ``MISSING``, ``OperationDef``,
``SecurityScheme``) needs nothing but the standard library; the client layer (``Client``, the
Results, ``Retry``, ``unwrap``) needs httpx, installed with the ``http`` extra
(``tsurara-client[http]``). Its names are imported on first use, so code generated with
``operations: false`` imports this package without httpx.
"""

from __future__ import annotations

import importlib
from typing import TYPE_CHECKING, Any

from ._auth import SecurityScheme
from ._codec import ConversionError, Converter, TypeDefs
from ._def import OPERATION_DEF_VERSION, OperationDef
from ._file import File
from ._missing import MISSING, Missing

if TYPE_CHECKING:
    from ._client import AsyncClient, Auth, Client, HeaderValues
    from ._info import OperationInfo, RequestInfo, UndocumentedStatusInfo
    from ._result import (
        AnyResult,
        HttpError,
        NetworkFailure,
        ParseFailure,
        Success,
        TimeoutFailure,
        TransportFailure,
        UndocumentedStatus,
        UnexpectedFailure,
    )
    from ._retry import Retry, retry_after
    from ._unwrap import ApiError, unwrap

__version__ = "0.1.1"

_CLIENT: dict[str, str] = {
    "AsyncClient": "._client",
    "Auth": "._client",
    "Client": "._client",
    "HeaderValues": "._client",
    "OperationInfo": "._info",
    "RequestInfo": "._info",
    "UndocumentedStatusInfo": "._info",
    "AnyResult": "._result",
    "HttpError": "._result",
    "NetworkFailure": "._result",
    "ParseFailure": "._result",
    "Success": "._result",
    "TimeoutFailure": "._result",
    "TransportFailure": "._result",
    "UndocumentedStatus": "._result",
    "UnexpectedFailure": "._result",
    "Retry": "._retry",
    "retry_after": "._retry",
    "ApiError": "._unwrap",
    "unwrap": "._unwrap",
}


def __getattr__(name: str) -> Any:
    module = _CLIENT.get(name)
    if module is None:
        raise AttributeError(f"module 'tsurara_client' has no attribute {name!r}")
    try:
        value = getattr(importlib.import_module(module, __name__), name)
    except ModuleNotFoundError as e:
        if e.name != "httpx":
            raise
        raise ImportError(
            f"tsurara_client.{name} needs httpx: install tsurara-client[http]",
            name=name,
        ) from e
    globals()[name] = value
    return value


__all__ = [
    "MISSING",
    "OPERATION_DEF_VERSION",
    "AnyResult",
    "ApiError",
    "AsyncClient",
    "Auth",
    "Client",
    "ConversionError",
    "Converter",
    "File",
    "HeaderValues",
    "HttpError",
    "Missing",
    "NetworkFailure",
    "OperationDef",
    "OperationInfo",
    "ParseFailure",
    "Retry",
    "SecurityScheme",
    "RequestInfo",
    "Success",
    "TimeoutFailure",
    "TransportFailure",
    "TypeDefs",
    "UndocumentedStatus",
    "UndocumentedStatusInfo",
    "UnexpectedFailure",
    "retry_after",
    "unwrap",
]
